cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# tiles 1 square, and L color2 missing TL, color3 missing BL, color4 missing TR
placements=[]
for r in range(6):
 for c in range(6):
  box={(r+i,c+j) for i in (0,1) for j in (0,1)}
  if box<=cells: placements.append((1,box,(r,c,'sq')))
  for color,missing in [(2,(r,c)),(3,(r+1,c)),(4,(r,c+1))]:
   tile=box-{missing}
   if tile<=cells: placements.append((color,tile,(r,c,'L')))
sol=[]
def rec(rem, chosen):
 if not rem: sol.append(chosen); return
 p=min(rem)
 for color,tile,loc in placements:
  if p in tile and tile<=rem: rec(rem-tile,chosen+[(color,tile,loc)])
rec(cells,[])
len(sol), [[(x[0],x[2]) for x in s] for s in sol[:20]]
